#include "tapas/objects/tlist.h"
#include "tapas/dsa/tstring.h"

#include "tapas/objects/tpair.h"
#include "../../dsa/tblockpool.h"

#include <stdint.h>
#include <stdlib.h>
#include <string.h>

/* Small lists keep their items inside the header allocation; growth
 * migrates out of the embedded tail (see tobj_vec_reserve). */
#define TLIST_INLINE_ITEMS 4

static tlist *tlist_new_cap(uint_count cap)
{
	if (cap > TLIST_INLINE_ITEMS) {
		tlist *list = (tlist *)tblockpool_alloc(sizeof(tlist));
		list->base.vtable = &tlist_vtable;
		list->base.refctr = 0;
		tobj_vec_init_cap(&list->items, cap);
		return list;
	}
	tlist *list = (tlist *)tblockpool_alloc(
		sizeof(tlist) + TLIST_INLINE_ITEMS * sizeof(tobj));
	list->base.vtable = &tlist_vtable;
	list->base.refctr = 0;
	list->items.data = (tobj *)(list + 1);
	list->items.len = 0;
	list->items.capacity = TLIST_INLINE_ITEMS;
	list->items.compo_count = 0;
	list->items.embedded = 1;
	return list;
}

/* Fill a pre-sized destination from a source range; replaces
 * tobj_vec_copy_range, which re-initializes (and would discard) the
 * destination's embedded storage. */
static void tlist_fill_range(tlist *dst, const tlist *src,
			     uint_count start, uint_count count)
{
	dst->items.len = count;
	if (!count)
		return;
	memcpy(dst->items.data, src->items.data + start,
	       count * sizeof(tobj));
	if (src->items.compo_count)
		for (uint_count i = 0; i < count; i++)
			if (dst->items.data[i].type == tcompo &&
			    dst->items.data[i].val.v_tcompo) {
				dst->items.data[i].val.v_tcompo->refctr++;
				dst->items.compo_count++;
			}
}

tlist *tlist_new(void)
{
	return tlist_new_cap(0);
}

tlist *tlist_new_sized(uint_count capacity)
{
	return tlist_new_cap(capacity);
}

tlist *tlist_replicate(const tlist *source, uint_count repetitions)
{
	uint_count source_len = tobj_vec_len(&source->items);
	if (source_len && repetitions > UINT32_MAX / source_len)
		twarn(ErrRuntime_Other, "replicate", "resulting list is too large");
	uint_count result_len = source_len * repetitions;
	tlist *result = tlist_new_cap(result_len);
	result->items.len = result_len;
	if (result_len) {
		memcpy(result->items.data, source->items.data,
		       source_len * sizeof(tobj));
		/* Re-copy the prefix already produced. This preserves the source
		 * pattern while reducing small memcpy calls from repetitions to
		 * logarithmic growth. */
		uint_count filled = source_len;
		while (filled < result_len) {
			uint_count copied = filled < result_len - filled ?
				filled : result_len - filled;
			memcpy(result->items.data + filled, result->items.data,
			       copied * sizeof(tobj));
			filled += copied;
		}
	}
	if (source->items.compo_count)
		for (uint_count i = 0; i < result_len; i++)
			if (result->items.data[i].type == tcompo &&
			    result->items.data[i].val.v_tcompo) {
				result->items.data[i].val.v_tcompo->refctr++;
				result->items.compo_count++;
			}
	return result;
}

void tlist_slice_index(tlist *l, const tobj *params, tobj *vre)
{
	/* params[0] is the end bound (pushed first), params[1] the start. */
	long first = params[1].val.v_tint;
	long last = params[0].val.v_tint;
	long len = (long)tobj_vec_len(&l->items);
	if (first < 0)
		first += len;
	if (last < 0)
		last += len;
	if (first < 0 || last < first || last > len)
		twarn(ErrRuntime_IdxOutRange, "pair_to_range", "");
	tlist *slice = tlist_new_cap((uint_count)(last - first));
	tlist_fill_range(slice, l, (uint_count)first,
			 (uint_count)(last - first));
	tobj_set_compo(vre, (tcompo_v *)slice);
}

uint_count tlist_size(const tlist *list)
{
	return tobj_vec_len(&list->items);
}

const tobj *tlist_at(const tlist *list, uint_count index)
{
	return tobj_vec_at_const(&list->items, index);
}

void tlist_set_at(tlist *list, uint_count index, const tobj *value)
{
	if (index >= tobj_vec_len(&list->items))
		twarn(ErrRuntime_IdxOutRange, "tlist_set_at", "");
	tobj_vec_set(&list->items, index, value);
}

/*----------------------- Required Vtable Operations -----------------------*/

static const char *tlist_get_type(void)
{
	return "List";
}


static long tlist_len(void *self)
{
	tlist *l = (tlist *)self;
	return (long)tobj_vec_len(&l->items);
}

static void *tlist_copy(void *self)
{
	tlist *l = (tlist *)self;
	tlist *n = tlist_new_cap(tobj_vec_len(&l->items));
	tlist_fill_range(n, l, 0, tobj_vec_len(&l->items));
	return n;
}

static void tlist_free(void *self)
{
	tlist *l = (tlist *)self;
	int embedded = l->items.embedded;
	tobj_vec_free(&l->items);
	tblockpool_free(l, embedded ?
		sizeof(tlist) + TLIST_INLINE_ITEMS * sizeof(tobj) :
		sizeof(tlist));
}

static int tlist_identical(void *self, void *other)
{
	tlist *a = (tlist *)self;
	tlist *b = (tlist *)other;
	if (tobj_vec_len(&a->items) != tobj_vec_len(&b->items))
		return 0;
	for (uint_count i = 0; i < tobj_vec_len(&a->items); i++) {
		if (!tobj_identical(tobj_vec_at(&a->items, i),
				    tobj_vec_at(&b->items, i)))
			return 0;
	}
	return 1;
}

/* Native List ordering is shared with sort/heap. Other objects retain
 * reflected operator dispatch; rhs preserves the original operand order. */
static void list_compare(void *self, const tobj *other, int rhs, tobj *out,
			 int operation)
{
	tobj value = { 0 };
	tobj_set_compo(&value, (tcompo_v *)self);
	if (tobj_compo_type(other) != compo_tlist) {
		/* Preserve the other object's reflected operator, including symbolic
		 * RuleTerm construction, which worked before List defined ordering. */
		compo_op_bin_fn reflected = nullptr;
		if (other->type == tcompo && other->val.v_tcompo) {
			const tcompo_vtable *table = other->val.v_tcompo->vtable;
			switch (operation) {
			case 0: reflected = table->op_sl; break;
			case 1: reflected = table->op_sg; break;
			case 2: reflected = table->op_le; break;
			default: reflected = table->op_ge; break;
			}
		}
		if (reflected) {
			reflected(other->val.v_tcompo, &value, !rhs, out);
			return;
		}
		twarn(ErrRuntime_ParamsType, "List comparison", "List required");
	}
	int order;
	if (!tobj_compare(&value, other, &order))
		twarn(ErrRuntime_ParamsType, "List comparison",
		      "incomparable elements, NaN or excessive nesting");
	if (rhs)
		order = -order;
	int result;
	switch (operation) {
	case 0: result = order < 0; break;
	case 1: result = order > 0; break;
	case 2: result = order <= 0; break;
	default: result = order >= 0; break;
	}
	tobj_set_bool(out, result);
}

static void list_lt(void *s, const tobj *v, int rhs, tobj *out)
{
	list_compare(s, v, rhs, out, 0);
}

static void list_gt(void *s, const tobj *v, int rhs, tobj *out)
{
	list_compare(s, v, rhs, out, 1);
}

static void list_le(void *s, const tobj *v, int rhs, tobj *out)
{
	list_compare(s, v, rhs, out, 2);
}

static void list_ge(void *s, const tobj *v, int rhs, tobj *out)
{
	list_compare(s, v, rhs, out, 3);
}

static tstring *tlist_tostring_abbr(void *self)
{
	return tobj_tostring_pointer("List", self);
}

static tstring *tlist_tostring_full(void *self)
{
	tlist *l = (tlist *)self;
	uint_count len = tobj_vec_len(&l->items);
	tstring *out = tstring_new("[");
	for (uint_count i = 0; i < len; i++) {
		tstring *item = tobj_tostring_full(tobj_vec_at(&l->items, i));
		tstring_append_ts(out, item);
		tstring_free(item);
		if (i < len - 1)
			tstring_append(out, ", ");
	}
	tstring_append_c(out, ']');
	return out;
}

/*------------------------------ Capabilities ------------------------------*/

/*
 * List implements every object capability: indexed reads and writes,
 * append, delete by index, membership testing, and iteration. List-only
 * operations such as push_front, push_back, pop_front, pop_back, insert,
 * concat and sort belong to stdlib.
 */

static int pair_to_range(const tobj *param, long len, long *start, long *end)
{
	if (param->type != tcompo || tobj_compo_type(param) != compo_tpair)
		return 0;
	tpair *pair = (tpair *)param->val.v_tcompo;
	if (pair->first.type != tint || pair->second.type != tint)
		twarn(ErrRuntime_ParamsType, "pair_to_range", "");
	long first = pair->first.val.v_tint;
	long last = pair->second.val.v_tint;
	if (first < 0)
		first += len;
	if (last < 0)
		last += len;
	if (first < 0 || last < first || last > len)
		twarn(ErrRuntime_IdxOutRange, "pair_to_range", "");
	*start = first;
	*end = last;
	return 1;
}

static int list_next(void *self, long *position, tobj *result)
{
	tlist *list = (tlist *)self;
	if (*position >= (long)tobj_vec_len(&list->items))
		return 0;
	*result = *tobj_vec_at(&list->items, (uint_count)*position);
	if (result->type == tcompo && result->val.v_tcompo)
		result->val.v_tcompo->refctr++;
	(*position)++;
	return 1;
}

static void list_append(void *self, const tobj *value)
{
	tobj_vec_push(&((tlist *)self)->items, value);
}

static void list_delete(void *self, const tobj *key)
{
	if (key->type != tint)
		twarn(ErrRuntime_ParamsType, "delete", "integer index required");
	tlist *list = (tlist *)self;
	long index = key->val.v_tint;
	if (index < 0)
		index += (long)tobj_vec_len(&list->items);
	if (index < 0 || (uint_count)index >= tobj_vec_len(&list->items))
		twarn(ErrRuntime_IdxOutRange, "delete", "");
	tobj_vec_pop(&list->items, (uint_count)index);
}

static int list_contains(void *self, const tobj *value)
{
	tlist *list = (tlist *)self;
	for (uint_count i = 0; i < tobj_vec_len(&list->items); i++)
		if (tobj_identical(tobj_vec_at(&list->items, i), value))
			return 1;
	return 0;
}

static void
tlist_idx(tlist *l, const tobj *params, uint_regs np, tobj *vre)
{
	if (np != 1)
		twarn(ErrRuntime_ParamsCtr, "tlist_idx", "");
	long start, end;
	if (pair_to_range(&params[0], (long)tobj_vec_len(&l->items), &start, &end)) {
		tlist *slice = tlist_new_cap((uint_count)(end - start));
		tlist_fill_range(slice, l, (uint_count)start,
				 (uint_count)(end - start));
		tobj_set_compo(vre, (tcompo_v *)slice);
		return;
	}
	if (params[0].type != tint)
		twarn(ErrRuntime_ParamsType, "tlist_idx", "");
	long idx = params[0].val.v_tint;
	uint_count len = tobj_vec_len(&l->items);
	if (idx < 0)
		idx += (long)len;
	if (idx < 0 || (uint_count)idx >= len)
		twarn(ErrRuntime_IdxOutRange, "tlist_idx", "");
	*vre = *tobj_vec_at(&l->items, (uint_count)idx);
	if (vre->type == tcompo && vre->val.v_tcompo)
		vre->val.v_tcompo->refctr++;
}

static void
tlist_iset(tlist *l, const tobj *params, uint_regs np, const tobj *vright)
{
	if (np != 1)
		twarn(ErrRuntime_ParamsCtr, "tlist_iset", "");
	if (params[0].type != tint)
		twarn(ErrRuntime_ParamsType, "tlist_iset", "");
	long idx = params[0].val.v_tint;
	uint_count len = tobj_vec_len(&l->items);
	if (idx < 0)
		idx += (long)len;
	if (idx < 0 || (uint_count)idx >= len)
		twarn(ErrRuntime_IdxOutRange, "tlist_iset", "");
	tlist_set_at(l, (uint_count)idx, vright);
}

static void list_index(void *self, const tobj *arguments,
		       uint_regs argument_count, tobj *result)
{
	tlist_idx((tlist *)self, arguments, argument_count, result);
}

static int list_try_index(void *self, const tobj *arguments,
			  uint_regs argument_count, tobj *result)
{
	tlist *list = (tlist *)self;
	if (argument_count != 1)
		twarn(ErrRuntime_ParamsCtr, "idx_or", "List needs one index");
	long len = (long)tobj_vec_len(&list->items);
	if (arguments[0].type == tint) {
		long index = arguments[0].val.v_tint;
		if (index < 0)
			index += len;
		if (index < 0 || index >= len)
			return 0;
		tobj_copy(result, &list->items.data[index]);
		return 1;
	}
	if (arguments[0].type == tcompo &&
	    tobj_compo_type(&arguments[0]) == compo_tpair) {
		tpair *range = (tpair *)arguments[0].val.v_tcompo;
		if (range->first.type != tint || range->second.type != tint)
			twarn(ErrRuntime_ParamsType, "idx_or",
			      "List slice bounds must be integers");
		long start = range->first.val.v_tint;
		long end = range->second.val.v_tint;
		if (start < 0) start += len;
		if (end < 0) end += len;
		if (start < 0 || end < start || end > len)
			return 0;
		tlist *slice = tlist_new_cap((uint_count)(end - start));
		tlist_fill_range(slice, list, (uint_count)start,
				 (uint_count)(end - start));
		tobj_set_compo(result, (tcompo_v *)slice);
		return 1;
	}
	twarn(ErrRuntime_ParamsType, "idx_or", "List index must be Int or Pair");
	return 0;
}

static void list_index_set(void *self, const tobj *arguments,
			   uint_regs argument_count, const tobj *value)
{
	tlist_iset((tlist *)self, arguments, argument_count, value);
}

static const tcompo_capabilities list_capabilities = {
	.indexable = list_index,
	.try_indexable = list_try_index,
	.index_settable = list_index_set,
	.appendable = list_append,
	.deletable = list_delete,
	.contains = list_contains,
	.iterable = list_next
};

tcompo_vtable tlist_vtable = {
	.get_type = tlist_get_type,
	.compo_code = compo_tlist,
	.len = tlist_len,
	.copy = tlist_copy,
	.free = tlist_free,
	.identical = tlist_identical,
	.tostring_abbr = tlist_tostring_abbr,
	.tostring_full = tlist_tostring_full,
	.op_sl = list_lt,
	.op_sg = list_gt,
	.op_le = list_le,
	.op_ge = list_ge,
	.capabilities = &list_capabilities
};

src/stdlib/heap/heap.c.source:
#include "tapas/textension.h"

#include "../arguments.h"

#include "tapas/objects/tlist.h"
#include "runtime/value_order.h"
#include "tapas/vm_service.h"

#include <math.h>


typedef struct {
	tlist *list;
	tobj less;
	tcompo_env *environment;
	const char *where;
} heap_order;

static tlist *require_list(const tobj *value, const char *where)
{
	if (tobj_compo_type(value) != compo_tlist)
		twarn(ErrRuntime_ParamsType, where, "List required");
	return (tlist *)value->val.v_tcompo;
}

static void require_orderable(const tobj *value, const char *where)
{
	if (!tobj_is_orderable(value))
		twarn(ErrRuntime_ParamsType, where,
		      "non-NaN number, String or recursively orderable List required");
}

static heap_order make_order(tobj *params, uint_regs len,
			     uint_regs required, const char *where,
			     tcompo_env *environment)
{
	if (len != required && len != required + 1)
		twarn(ErrRuntime_ParamsCtr, where,
		      "optional final comparator expected");
	heap_order order = {
		.list = require_list(&params[0], where),
		.environment = environment,
		.where = where
	};
	tobj_set_nil(&order.less);
	if (len > required) {
		/* Native argument slots can move when a callback grows the VM stack.
		 * Keep a borrowed value, rather than a pointer to one of those slots. */
		order.less = params[required];
		tcompo_type type = tobj_compo_type(&order.less);
		if (type != compo_tfunc && type != compo_cppfunc &&
		    type != compo_sessfunc)
			twarn(ErrRuntime_ParamsType, where,
			      "comparator must be a Function");
	}
	return order;
}

static int less_at(const heap_order *order, uint_count left, uint_count right)
{
	tobj_vec *items = &order->list->items;
	const tobj *a = &items->data[left];
	const tobj *b = &items->data[right];
	if (order->less.type == tnil) {
		/* Keep homogeneous numeric heaps on their direct scalar paths. */
		if (a->type == tint && b->type == tint)
			return a->val.v_tint < b->val.v_tint;
		if (a->type == tfloat && b->type == tfloat) {
			if (isnan(a->val.v_tfloat) || isnan(b->val.v_tfloat))
				twarn(ErrRuntime_ParamsType, order->where, "NaN is not orderable");
			return a->val.v_tfloat < b->val.v_tfloat;
		}
		int comparison;
		int valid = a->type != tcompo && b->type != tcompo ?
			tobj_compare_numbers(a, b, &comparison) :
			tobj_compare(a, b, &comparison);
		if (!valid)
			twarn(ErrRuntime_ParamsType, order->where,
			      "incomparable elements, NaN or excessive nesting");
		return comparison < 0;
	}

	/* The list owns these borrowed values; VM function frames retain their
	 * parameters before running user code. Keep no buffer pointers or extra
	 * owned references across an invocation, which may raise an error. */
	tobj arguments[2] = {*a, *b};
	tobj answer;
	tobj_set_nil(&answer);
	uint_count size = items->len;
	tobj *data = items->data;
	tvm_services_invoke(order->environment, &order->less, arguments, 2, &answer);
	int valid = answer.type == tbool;
	int less = valid && answer.val.v_tbool;
	tobj_ddc_ref_clear(&answer);
	if (items->len != size || items->data != data)
		twarn(ErrRuntime_Other, order->where,
		      "comparator must not modify the heap");
	if (!valid)
		twarn(ErrRuntime_ParamsType, order->where,
		      "comparator must return Bool");
	return less;
}

/* Swaps transfer owned references; the vector's composite count is unchanged.
 * Every comparison sees a complete list, even if a callback raises an error. */
static void swap_items(tlist *list, uint_count a, uint_count b)
{
	tobj temporary = list->items.data[a];
	list->items.data[a] = list->items.data[b];
	list->items.data[b] = temporary;
}

static void sift_down(const heap_order *order, uint_count parent, uint_count size)
{
	while (parent < size / 2) {
		uint_count child = parent * 2 + 1;
		if (child + 1 < size && less_at(order, child + 1, child))
			child++;
		if (!less_at(order, child, parent))
			break;
		swap_items(order->list, parent, child);
		parent = child;
	}
}

/* Pop replaces the root with a leaf value, which usually travels downward.
 * Compare siblings on the descent, then settle the replacement upward.
 * Swaps keep every payload rooted in the List across fallible callbacks. */
static void sift_pop(const heap_order *order, uint_count parent, uint_count size)
{
	if (parent >= size / 2)
		return;
	uint_count child = parent * 2 + 1;
	if (child + 1 < size && less_at(order, child + 1, child))
		child++;
	/* Equal priorities and replacements already in order need no movement.
	 * Otherwise the first comparison proves the replacement cannot rise
	 * above this child again, so exclude the settled root on the ascent. */
	if (!less_at(order, child, parent))
		return;
	swap_items(order->list, parent, child);
	parent = child;
	uint_count start = parent;
	while (parent < size / 2) {
		child = parent * 2 + 1;
		if (child + 1 < size && less_at(order, child + 1, child))
			child++;
		swap_items(order->list, parent, child);
		parent = child;
	}
	while (parent > start) {
		uint_count previous = (parent - 1) / 2;
		if (!less_at(order, parent, previous))
			break;
		swap_items(order->list, parent, previous);
		parent = previous;
	}
}

static void heap_heapify(tobj *params, uint_regs len, tobj *result,
			 tcompo_env *environment)
{
	heap_order order = make_order(params, len, 1, "heap::heapify", environment);
	uint_count size = tlist_size(order.list);
	if (order.less.type == tnil)
		for (uint_count i = 0; i < size; i++)
			require_orderable(tlist_at(order.list, i), order.where);
	for (uint_count i = size / 2; i > 0; i--)
		sift_down(&order, i - 1, size);
	tobj_set_nil(result);
}

static void heap_push(tobj *params, uint_regs len, tobj *result,
		      tcompo_env *environment)
{
	heap_order order = make_order(params, len, 2, "heap::push", environment);
	if (order.less.type == tnil)
		require_orderable(&params[1], order.where);
	uint_count child = tlist_size(order.list);
	tobj_vec_push(&order.list->items, &params[1]);
	while (child > 0) {
		uint_count parent = (child - 1) / 2;
		if (!less_at(&order, child, parent))
			break;
		swap_items(order.list, child, parent);
		child = parent;
	}
	tobj_set_nil(result);
}

static void heap_pop(tobj *params, uint_regs len, tobj *result,
		     tcompo_env *environment)
{
	heap_order order = make_order(params, len, 1, "heap::pop", environment);
	uint_count size = tlist_size(order.list);
	if (!size)
		twarn(ErrRuntime_IdxOutRange, order.where, "heap is empty");
	/* Keep the removed value in the list during comparisons, so an error
	 * cannot strand an owned payload in a C local. Exclude it while sifting. */
	swap_items(order.list, 0, size - 1);
	sift_pop(&order, 0, size - 1);
	tobj_vec_take(&order.list->items, size - 1, result);
}

static void heap_peek(tobj *params, uint_regs len, tobj *result)
{
	tstdlib_require_arguments("heap::peek", len, 1);
	tlist *list = require_list(&params[0], "heap::peek");
	if (!tlist_size(list))
		twarn(ErrRuntime_IdxOutRange, "heap::peek", "heap is empty");
	tobj_copy(result, tlist_at(list, 0));
}

static const textension_symbol symbols[] = {
	{
		.name = "heapify",
		.type = "Function[...] -> Nil",
		.detail = "heap::heapify(items: List[, less: Function]) -> Nil",
		.kind = textension_function,
		.session_function = heap_heapify,
		.minimum_arguments = 1,
		.maximum_arguments = 2
	},
	{
		.name = "push",
		.type = "Function[...] -> Nil",
		.detail = "heap::push(items: List, value: AnyType[, less: Function]) -> Nil",
		.kind = textension_function,
		.session_function = heap_push,
		.minimum_arguments = 2,
		.maximum_arguments = 3
	},
	{
		.name = "pop",
		.type = "Function[...] -> AnyType",
		.detail = "heap::pop(items: List[, less: Function]) -> AnyType",
		.kind = textension_function,
		.session_function = heap_pop,
		.minimum_arguments = 1,
		.maximum_arguments = 2
	},
	{
		.name = "peek",
		.type = "Function[List] -> AnyType",
		.detail = "heap::peek(items: List) -> AnyType",
		.kind = textension_function,
		.function = heap_peek,
		.minimum_arguments = 1,
		.maximum_arguments = 1
	}
};

const textension_module tstdlib_heap_module = {
	.scope = textension_package,
	.name = "heap",
	.detail = "In-place binary heaps with optional comparators",
	.symbols = symbols,
	.symbol_count = sizeof(symbols) / sizeof(symbols[0])
};

