#include "tapas/textension.h"

#include "../arguments.h"

#include "tapas/objects/tlist.h"
#include "runtime/value_order.h"

#include <stdlib.h>

/* No user callbacks run here. Defer comparison errors until qsort returns:
 * raising while qsort holds a moved item could strand an owned reference.
 * Validated inputs give tobj_compare a consistent category-order fallback
 * on mismatches, preserving qsort's comparator requirements before error. */
static _Thread_local int comparison_failed;

static int compare_values(const void *left, const void *right)
{
	const tobj *a = left;
	const tobj *b = right;
	int order = 0;
	int valid = a->type != tcompo && b->type != tcompo ?
		tobj_compare_numbers(a, b, &order) : tobj_compare(a, b, &order);
	if (!valid)
		comparison_failed = 1;
	return order;
}

/* Pick scalar comparators once after validation. Keeping them as leaf
 * functions avoids per-comparison tags and generic dispatch register costs. */
static int compare_integers(const void *left, const void *right)
{
	long a = ((const tobj *)left)->val.v_tint;
	long b = ((const tobj *)right)->val.v_tint;
	return (a > b) - (a < b);
}

static int compare_floats(const void *left, const void *right)
{
	double a = ((const tobj *)left)->val.v_tfloat;
	double b = ((const tobj *)right)->val.v_tfloat;
	return (a > b) - (a < b);
}

static void builtin_sort(tobj *params, uint_regs len, tobj *result)
{
	tstdlib_require_arguments("sort", len, 1);
	if (params[0].type != tcompo ||
	    tobj_compo_type(&params[0]) != compo_tlist)
		twarn(ErrRuntime_ParamsType, "sort", "");
	tlist *list = (tlist *)params[0].val.v_tcompo;
	ttypes homogeneous = list->items.len ? list->items.data[0].type : tnil;
	for (uint_count i = 0; i < list->items.len; i++) {
		if (list->items.data[i].type != homogeneous)
			homogeneous = tnil;
		if (list->items.data[i].type != tint &&
		    !tobj_is_orderable(&list->items.data[i]))
			twarn(ErrRuntime_ParamsType, "sort",
			      "non-NaN number, String or recursively orderable List required");
	}
	int (*compare)(const void *, const void *) = compare_values;
	if (homogeneous == tint)
		compare = compare_integers;
	else if (homogeneous == tfloat)
		compare = compare_floats;
	comparison_failed = 0;
	qsort(tobj_vec_data(&list->items), tobj_vec_len(&list->items),
	      sizeof(tobj), compare);
	if (comparison_failed)
		twarn(ErrRuntime_ParamsType, "sort", "incomparable elements");
	tobj_set_nil(result);
}

static const textension_symbol symbols[] = {
	{
		.name = "sort",
		.type = "Function[List] -> Nil",
		.detail = "sort(values: List) -> Nil",
		.kind = textension_function,
		.function = builtin_sort,
		.minimum_arguments = 1,
		.maximum_arguments = 1
	}
};

const textension_module tstdlib_sort_functions = {
	.scope = textension_root,
	.symbols = symbols,
	.symbol_count = sizeof(symbols) / sizeof(symbols[0])
};

test/unit/test_value_order.c.source:
#include "tapas/objects/tlist.h"
#include "tapas/objects/tstr.h"

#include <assert.h>
#include <limits.h>
#include <math.h>

int main(void)
{
	tobj a = { 0 }, b = { 0 };
	int order;
	const long integers[] = { LONG_MIN, -9007199254740993L, -1, 0,
		1, 9007199254740993L, LONG_MAX };
	const double reals[] = { -INFINITY, (double)LONG_MIN, -9007199254740992.0,
		-0.5, -0.0, 0.5, 9007199254740992.0, -(double)LONG_MIN, INFINITY };
	for (unsigned i = 0; i < sizeof(integers) / sizeof(*integers); i++) {
		for (unsigned j = 0; j < sizeof(reals) / sizeof(*reals); j++) {
			tobj_set_int(&a, integers[i]);
			tobj_set_float(&b, reals[j]);
			assert(tobj_compare(&a, &b, &order));
			int reverse;
			assert(tobj_compare(&b, &a, &reverse));
			assert(order == -reverse);
		}
	}
	tobj_set_float(&a, NAN);
	assert(!tobj_is_orderable(&a));
	assert(!tobj_compare(&a, &a, &order));
	const char left[] = { 'a', '\0', 'b' };
	const char right[] = { 'a', '\0', 'c' };
	tobj_set_compo(&a, (tcompo_v *)tstr_new_len(left, sizeof(left)));
	tobj_set_compo(&b, (tcompo_v *)tstr_new_len(right, sizeof(right)));
	assert(tobj_compare(&a, &b, &order) && order < 0);
	tobj_try_clear(&a);
	tobj_try_clear(&b);
	// Reject cycles without leaving a recursive depth counter poisoned.
	tlist *cycle = tlist_new();
	tobj_set_compo(&a, (tcompo_v *)cycle);
	a.val.v_tcompo->refctr++;
	tobj_vec_push(&cycle->items, &a);
	assert(!tobj_is_orderable(&a));
	assert(!tobj_compare(&a, &a, &order));
	tobj_set_int(&b, 3);
	tlist_set_at(cycle, 0, &b);
	assert(tobj_is_orderable(&a));
	assert(tobj_compare(&a, &a, &order) && order == 0);
	tobj_ddc_ref_clear(&a);
	// Sort must retain a transitive fallback even for incompatible categories.
	tobj values[7] = { 0 };
	tobj_set_int(&values[0], 1);
	tobj_set_float(&values[1], 1.0);
	tobj_set_compo(&values[2], (tcompo_v *)tstr_new("a"));
	for (unsigned i = 3; i < 7; i++) {
		tlist *list = tlist_new();
		tobj_vec_push(&list->items, &values[i - 3]);
		tobj_set_compo(&values[i], (tcompo_v *)list);
	}
	for (unsigned i = 0; i < 7; i++)
		if (values[i].type == tcompo)
			values[i].val.v_tcompo->refctr++;
	for (unsigned i = 0; i < 7; i++) {
		assert(tobj_is_orderable(&values[i]));
		for (unsigned j = 0; j < 7; j++) {
			int ij, ji;
			tobj_compare(&values[i], &values[j], &ij);
			tobj_compare(&values[j], &values[i], &ji);
			assert(ij == -ji);
			for (unsigned k = 0; k < 7; k++) {
				int jk, ik;
				tobj_compare(&values[j], &values[k], &jk);
				tobj_compare(&values[i], &values[k], &ik);
				assert(!(ij <= 0 && jk <= 0) || ik <= 0);
			}
		}
	}
	for (unsigned i = 7; i > 0; i--)
		tobj_ddc_ref_clear(&values[i - 1]);
	return 0;
}
